/** Original synthesized effects. Audio starts only after an input gesture. */
export class Sound{constructor(){this.ctx=null;this.nodes=new Set();this.settings={sound:true,volume:.35};}set(settings){this.settings=settings;if(!settings.sound||!settings.volume)this.stop();}unlock(){try{if(!this.ctx)this.ctx=new (window.AudioContext||window.webkitAudioContext)();if(this.ctx.state==='suspended')this.ctx.resume().catch(()=>{});}catch{}}stop(){for(const n of this.nodes){try{n.stop();}catch{}}this.nodes.clear();}play(kind){if(!this.ctx||!this.settings.sound||!this.settings.volume||this.ctx.state!=='running')return;const tunes={click:[[420,0,.055]],hover:[[700,0,.022]],drop:[[430,0,.09],[280,.04,.09]],land:[[160,0,.1],[310,.025,.06]],invalid:[[120,0,.11],[100,.08,.08]],turn:[[610,0,.055]],win:[[523,0,.12],[659,.1,.13],[784,.2,.2],[1046,.34,.32]],champion:[[523,0,.15],[659,.12,.15],[784,.24,.16],[1046,.38,.45],[1318,.5,.35]],draw:[[440,0,.18],[349,.15,.22]],menu:[[440,0,.06],[660,.05,.09]]};for(const [freq,delay,duration] of tunes[kind]??tunes.click){const o=this.ctx.createOscillator(),g=this.ctx.createGain(),t=this.ctx.currentTime+delay;o.type=kind==='land'?'triangle':'sine';o.frequency.setValueAtTime(freq,t);if(kind==='drop')o.frequency.exponentialRampToValueAtTime(freq*.55,t+duration);g.gain.setValueAtTime(.001,t);g.gain.exponentialRampToValueAtTime(.11*this.settings.volume,t+.008);g.gain.exponentialRampToValueAtTime(.001,t+duration);o.connect(g);g.connect(this.ctx.destination);o.start(t);o.stop(t+duration+.02);this.nodes.add(o);o.onended=()=>{this.nodes.delete(o);o.disconnect();g.disconnect();};}}}
